fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    if down == 1 && prev == 0 {
        if px >= 20 && px < 140 && py >= 20 && py < 60 {
            host::display::state_set(0, 1 - host::display::state_get(0));
        }
    }
    host::display::state_set(1, down);
    let mut bg: i32 = 0x101010;
    let mut fg: i32 = 0xffffff;
    if host::display::state_get(0) == 1 {
        bg = 0xf0f0f0;
        fg = 0x101010;
    }
    host::display::clear(bg);
    host::display::fill_rect(20, 20, 120, 40, 0x3060a0);
    host::display::draw_string(40, 32, "THEME", fg, 2);
    host::display::present();
}
